// COE305 compositions (registered in ../Root.tsx). Generated by gen_index.py; narration in ../../scripts/coe305.py.
import React from 'react';
import { Composition } from 'remotion';
import { makeTL } from '../lib';
import { MlActivation } from './Activation';
import tActivation from '../timelines/ml-activation.json';
import { MlEntropy } from './Entropy';
import tEntropy from '../timelines/ml-entropy.json';
import { MlFeatures } from './Features';
import tFeatures from '../timelines/ml-features.json';
import { MlKinds } from './Kinds';
import tKinds from '../timelines/ml-kinds.json';
import { MlNeuron } from './Neuron';
import tNeuron from '../timelines/ml-neuron.json';
import { MlRate } from './Rate';
import tRate from '../timelines/ml-rate.json';

const comp = (id: string, component: React.FC, t: unknown) => {
  const { TL } = makeTL(t);
  return <Composition key={id} id={id} component={component} durationInFrames={TL.total} fps={TL.fps} width={1920} height={1080} />;
};

export const MlComps: React.FC = () => <>
  {comp('MlActivation', MlActivation, tActivation)}
  {comp('MlEntropy', MlEntropy, tEntropy)}
  {comp('MlFeatures', MlFeatures, tFeatures)}
  {comp('MlKinds', MlKinds, tKinds)}
  {comp('MlNeuron', MlNeuron, tNeuron)}
  {comp('MlRate', MlRate, tRate)}
</>;
